+/**
+ * Sanitization utilities for embed content to prevent XSS attacks.
+ * This module provides functions to safely handle untrusted HTML content
+ * in iframes, particularly for the srcdoc attribute.
+ */
+
+import { EMBEDDABLE_HOSTS } from "./constants";
+
+// Characters that need HTML escaping
+const HTML_ESCAPE_MAP: Record<string, string> = {
+  "&": "&amp;",
+  "<": "&lt;",
+  ">": "&gt;",
+  '"': "&quot;",
+  "'": "&#x27;",
+  "/": "&#x2F;",
+};
+
+/**
+ * Escapes HTML special characters in a string.
+ * This prevents HTML injection when the string is placed in an HTML context.
+ */
+const escapeHtml = (str: string): string => {
+  return str.replace(/[&<>"'/]/g, (char) => HTML_ESCAPE_MAP[char] || char);
+};
+
+/**
+ * Escapes a string for safe use in an HTML attribute value.
+ * This handles both double and single quoted attributes.
+ */
+const escapeAttribute = (value: string): string => {
+  // First escape HTML entities, then escape quotes
+  const htmlEscaped = escapeHtml(value);
+  // Replace quotes with their entity equivalents for use in attributes
+  return htmlEscaped
+    .replace(/"/g, "&quot;")
+    .replace(/'/g, "&#x27;");
+};
+
+/**
+ * Creates a sanitized srcdoc content for iframes.
+ * This ensures that untrusted content cannot execute JavaScript
+ * even if the iframe has allow-same-origin sandbox permissions.
+ */
+export const createSafeSrcdoc = (
+  url: string,
+  title?: string
+): string => {
+  const escapedUrl = escapeAttribute(url);
+  const escapedTitle = escapeAttribute(title || "");
+
+  return `<!DOCTYPE html>
+<html>
+<head>
+  <meta charset="UTF-8">
+  <base target="_blank">
+  <style>
+    body { margin: 0; display: flex; align-items: center; justify-content: center; height: 100vh; background: transparent; }
+    iframe { width: 100%; height: 100%; border: none; }
+  </style>
+</head>
+<body>
+  <a href="${escapedUrl}" target="_blank" rel="noopener noreferrer" title="${escapedTitle}">
+    Click to open: ${escapedTitle}
+  </a>
+</body>
+</html>`;
+};
+
+/**
+ * Generates a safe embed HTML for iframes.
+ * This is used when embedding content from untrusted sources.
+ *
+ * The function constructs the HTML manually and escapes all user-controlled
+ * values to prevent XSS attacks through attribute injection or script injection.
+ */
+export const sanitizeEmbedCode = (
+  url: string,
+  hint: { renderedText?: string; width?: number; height?: number },
+  host: string
+): string => {
+  // Validate and sanitize the URL
+  let safeUrl = url;
+  try {
+    const parsedUrl = new URL(url);
+    // Only allow http and https protocols
+    if (!["http:", "https:"].includes(parsedUrl.protocol)) {
+      safeUrl = "about:blank";
+    }
+  } catch {
+    safeUrl = "about:blank";
+  }
+
+  const escapedUrl = escapeAttribute(safeUrl);
+  const escapedHost = escapeHtml(host);
+  const escapedText = escapeHtml(hint.renderedText || "");
+  const width = Math.min(Math.max(Number(hint.width) || 300, 100), 2000);
+  const height = Math.min(Math.max(Number(hint.height) || 150, 100), 2000);
+
+  // Check if this is a known embeddable host that can be safely iframed
+  const isTrustedEmbed = EMBEDDABLE_HOSTS.some(
+    (trustedHost) =>
+      trustedHost.host.test(parsedUrl?.hostname || "") ||
+      safeUrl.includes(trustedHost.host.source)
+  );
+
+  // Build the srcdoc content manually with all values escaped
+  // This prevents any injection through URL or text parameters
+  const srcdoc = `<!DOCTYPE html>
+<html>
+<head>
+  <meta charset="UTF-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1.0">
+  <base target="_blank">
+  <style>
+    * { margin: 0; padding: 0; box-sizing: border-box; }
+    html, body { width: 100%; height: 100%; background: transparent; }
+    .container { width: ${width}px; height: ${height}px; display: flex; flex-direction: column; }
+    iframe { width: 100%; height: 100%; border: none; }
+    .fallback { display: flex; flex-direction: column; align-items: center; justify-content: center;
+                 padding: 16px; text-align: center; font-family: system-ui, sans-serif; font-size: 14px; }
+    a { color: #1971c2; text-decoration: none; }
+    a:hover { text-decoration: underline; }
+  </style>
+</head>
+<body>
+  <div class="container">
+    ${isTrustedEmbed
+      ? `<iframe src="${escapedUrl}" loading="lazy" title="${escapedText}"></iframe>`
+      : `<div class="fallback">
+           <p>Content from <strong>${escapedHost}</strong></p>
+           <p style="margin-top: 8px;">${escapedText || "Click to open in new tab"}</p>
+           <a href="${escapedUrl}" rel="noopener noreferrer" target="_blank" style="margin-top: 12px;">
+             Open ${escapedHost} ↗
+           </a>
+         </div>`
+    }
+  </div>
+</body>
+</html>`;
+
+  return srcdoc;
+};
+
+/**
+ * Validates whether a URL is from a trusted embeddable host.
+ */
+export const isTrustedEmbedHost = (url: string): boolean => {
+  try {
+    const parsedUrl = new URL(url);
+    return EMBEDDABLE_HOSTS.some((trustedHost) =>
+      trustedHost.host.test(parsedUrl.hostname)
+    );
+  } catch {
+    return false;
+  }
+};
+
+/**
+ * Gets the appropriate sandbox attribute for an iframe based on content trust.
+ * For untrusted content, only allow-scripts is used (no allow-same-origin).
+ * For trusted embeds, allow-same-origin may be added if needed.
+ */
+export const getSandboxAttributes = (
+  isTrusted: boolean,
+  needsSameOrigin: boolean = false
+): string => {
+  if (isTrusted && needsSameOrigin) {
+    return "allow-same-origin allow-scripts";
+  }
+  // Always exclude allow-same-origin for untrusted content to prevent XSS
+  return "allow-scripts";
+};

